package io.github.pluginprofiler;

import net.runelite.api.Client;

/**
 * A point-in-time view of the RuneLite client thread's Java stack, captured by the
 * sampler worker with {@link Thread#getStackTrace()}. Frame zero is the innermost
 * call. The stack shows where the thread was executing or waiting at capture time.
 */
final class ClientThreadStack
{
    private static final ClientThreadStack EMPTY = new ClientThreadStack(new StackTraceElement[0]);
    private final StackTraceElement[] frames;

    ClientThreadStack(StackTraceElement[] frames)
    {
        this.frames = frames;
    }

    /** Looks up the current client thread for each sample. An unavailable thread yields an empty stack. */
    static ClientThreadStack capture(Client client)
    {
        return read(client.getClientThread());
    }

    static ClientThreadStack read(Thread thread)
    {
        return thread == null ? EMPTY : new ClientThreadStack(thread.getStackTrace());
    }

    int size()
    {
        return frames.length;
    }

    String classNameAt(int index)
    {
        return frames[index].getClassName();
    }

    /** Formats one class and method name for the in-memory call path. */
    String frameNameAt(int index)
    {
        StackTraceElement frame = frames[index];
        return frame.getClassName() + "." + frame.getMethodName();
    }
}

package io.github.pluginprofiler;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** One immutable roster of eligible owners. Its observation caches belong to the sampler. */
final class OwnershipIndex
{
    enum Evidence { UNKNOWN, GUESS, LEARNED, ALIAS }
    static final int AMBIGUOUS = -1;

    static final class Owner
    {
        final int id;
        final String name;
        final String group;
        final boolean active;

        Owner(int id, String name, String group, boolean active)
        {
            this.id = id;
            this.name = name;
            this.group = group;
            this.active = active;
        }
    }

    static final class Match
    {
        final int id;
        final Evidence evidence;
        Match(int id, Evidence evidence) { this.id = id; this.evidence = evidence; }
    }

    static final Match UNKNOWN = new Match(0, Evidence.UNKNOWN);

    static final class Learned
    {
        private final Map<String, Integer> callers = new HashMap<>();
        private final Map<String, Integer> helpers = new HashMap<>();
        private long revision;

        private void witness(String helper, int owner, boolean local)
        {
            Integer previousCaller = callers.putIfAbsent(helper, owner);
            if (previousCaller != null && previousCaller != owner)
            {
                callers.put(helper, AMBIGUOUS);
                owner = AMBIGUOUS;
            }
            // A foreign caller can invalidate a learned helper, but cannot claim one.
            if (!local && owner != AMBIGUOUS) { return; }
            Integer old = helpers.put(helper, owner);
            if (old == null || old != owner) { revision++; }
        }
    }

    private static final class Candidate
    {
        final String name;
        final String pkg;
        final Match direct;
        final boolean entry;

        Candidate(String name, String pkg, Match direct, boolean entry)
        {
            this.name = name;
            this.pkg = pkg;
            this.direct = direct;
            this.entry = entry;
        }

        @Override public boolean equals(Object other)
        {
            if (this == other) { return true; }
            if (!(other instanceof Candidate)) { return false; }
            Candidate c = (Candidate) other;
            return name.equals(c.name) && direct.id == c.direct.id && direct.evidence == c.direct.evidence;
        }

        @Override public int hashCode() { return name.hashCode(); }
    }

    /** Recent observations and one session counter share the same revisable ownership decision. */
    static final class Signature
    {
        private final List<Candidate> classes;
        private final Set<Integer> active;
        private final int hash;
        private long revision = -1;
        private Match match = UNKNOWN;

        Signature(List<Candidate> classes, Set<Integer> active)
        {
            this.classes = classes;
            this.active = classes.isEmpty() ? Set.of() : active;
            this.hash = 31 * classes.hashCode() + this.active.hashCode();
        }

        // Rebuilding a roster must not create another session counter for equivalent evidence.
        // The cached resolution can change as we learn; only the facts at capture time identify a key.
        @Override public boolean equals(Object other)
        {
            if (this == other) { return true; }
            if (!(other instanceof Signature)) { return false; }
            Signature s = (Signature) other;
            return hash == s.hash && classes.equals(s.classes) && active.equals(s.active);
        }

        @Override public int hashCode() { return hash; }

        Match resolve(Learned learned)
        {
            if (revision == learned.revision) { return match; }
            Match best = UNKNOWN;
            for (Candidate c : classes)
            {
                best = combine(best, c.direct);
                int owner = learned.helpers.getOrDefault(c.name, 0);
                if (owner == AMBIGUOUS || active.contains(owner))
                {
                    best = combine(best, new Match(owner, Evidence.LEARNED));
                }
            }
            match = best.id > 0 ? best : UNKNOWN;
            revision = learned.revision;
            return match;
        }

        private static Match combine(Match a, Match b)
        {
            if (a.evidence == b.evidence && a.id != b.id) { return new Match(AMBIGUOUS, a.evidence); }
            return b.evidence.ordinal() > a.evidence.ordinal() ? b : a;
        }

        void learn(Learned learned)
        {
            Candidate anchor = null;
            for (Candidate c : classes)
            {
                if (c.entry && c.direct.evidence == Evidence.ALIAS && c.direct.id > 0) { anchor = c; }
            }
            if (anchor == null) { return; }
            for (Candidate c : classes)
            {
                if (c.direct.evidence == Evidence.ALIAS && c.direct.id != anchor.direct.id) { return; }
            }
            for (Candidate c : classes)
            {
                if (c == anchor)
                {
                    learned.witness(c.name, anchor.direct.id, true);
                    break;
                }
                if (c.direct.evidence != Evidence.ALIAS && !c.entry)
                {
                    learned.witness(c.name, anchor.direct.id, c.pkg.equals(anchor.pkg));
                }
            }
        }
    }

    static final class Observation
    {
        final Signature signature;
        final String path;
        Observation(Signature signature, String path) { this.signature = signature; this.path = path; }
    }

    private final Set<Integer> active = new HashSet<>();
    private final Map<String, Integer> aliases = new HashMap<>();
    private final Map<String, Candidate> candidates = new HashMap<>();
    private final Map<List<Candidate>, Signature> signatures = new HashMap<>();

    OwnershipIndex(Collection<Owner> roster)
    {
        for (Owner owner : roster)
        {
            if (owner.active) { active.add(owner.id); }
            alias(owner.name, owner.id);
            if (owner.group != null && !owner.group.equalsIgnoreCase("runelite")) { alias(owner.group, owner.id); }
        }
    }

    private void alias(String raw, int id)
    {
        String name = normalize(raw);
        if (!name.isEmpty()) { aliases.merge(name, id, (a, b) -> a.equals(b) ? a : AMBIGUOUS); }
    }

    Observation observe(ClientThreadStack stack, Learned learned)
    {
        List<Candidate> seen = new ArrayList<>();
        int lastCandidate = -1;
        int lastAlias = -1;
        for (int i = 0; i < stack.size(); i++)
        {
            String name = stack.classNameAt(i);
            int nested = name.indexOf('$');
            if (nested >= 0) { name = name.substring(0, nested); }
            if (!eligibleClass(name)) { continue; }
            Candidate c = candidates.computeIfAbsent(name, this::candidate);
            if (!seen.contains(c)) { seen.add(c); }
            lastCandidate = i;
            if (c.direct.id > 0) { lastAlias = i; }
        }
        Signature signature = signatures.get(seen);
        if (signature == null)
        {
            signature = new Signature(seen, active);
            signatures.put(seen, signature);
            signature.learn(learned);
        }
        int caller = lastAlias >= 0 ? lastAlias : lastCandidate;
        return new Observation(signature, caller < 0 ? null : path(stack, caller));
    }

    private static boolean eligibleClass(String name)
    {
        return name.indexOf('.') > 0 && (!name.startsWith("net.runelite.") || name.startsWith("net.runelite.client.plugins."))
            && !name.startsWith("java.") && !name.startsWith("javax.") && !name.startsWith("jdk.")
            && !name.startsWith("sun.") && !name.startsWith("com.sun.") && !name.startsWith("com.google.")
            && !name.startsWith("org.lwjgl.") && !name.startsWith("org.slf4j.");
    }

    private Candidate candidate(String name)
    {
        int dot = name.lastIndexOf('.');
        String simple = name.substring(dot + 1);
        for (String suffix : SUFFIXES)
        {
            if (simple.endsWith(suffix))
            {
                String stem = normalize(simple.substring(0, simple.length() - suffix.length()));
                return new Candidate(name, name.substring(0, dot), guess(stem), suffix.equals("Plugin"));
            }
        }
        return new Candidate(name, name.substring(0, dot), UNKNOWN, false);
    }

    private static final String[] SUFFIXES = {"Plugin", "Overlay", "Panel"};

    private Match guess(String stem)
    {
        if (stem.length() < 3) { return UNKNOWN; }
        Integer exact = aliases.get(stem);
        if (exact != null) { return new Match(active.contains(exact) ? exact : AMBIGUOUS, Evidence.ALIAS); }
        if (stem.length() < 7 || stem.length() > 80) { return UNKNOWN; }
        int limit = stem.length() < 12 ? 1 : 2;
        int first = limit + 2;
        int second = first;
        int winner = 0;
        for (Map.Entry<String, Integer> alias : aliases.entrySet())
        {
            if (Math.abs(stem.length() - alias.getKey().length()) > limit + 1) { continue; }
            int distance = editDistance(stem, alias.getKey());
            if (distance < first)
            {
                if (alias.getValue() != winner) { second = first; }
                first = distance;
                winner = alias.getValue();
            }
            else if (alias.getValue() != winner && distance < second) { second = distance; }
        }
        if (first > limit) { return UNKNOWN; }
        return new Match(active.contains(winner) && second - first >= 2 ? winner : AMBIGUOUS, Evidence.GUESS);
    }

    private static int editDistance(String a, String b)
    {
        int[] row = new int[b.length() + 1];
        for (int j = 0; j < row.length; j++) { row[j] = j; }
        for (int i = 1; i <= a.length(); i++)
        {
            int diagonal = row[0];
            row[0] = i;
            for (int j = 1; j < row.length; j++)
            {
                int previous = row[j];
                int cost = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                row[j] = Math.min(diagonal + cost, Math.min(previous, row[j - 1]) + 1);
                diagonal = previous;
            }
        }
        return row[b.length()];
    }

    private static String normalize(String name) { return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", ""); }

    private static String path(ClientThreadStack stack, int caller)
    {
        List<String> parts = new ArrayList<>();
        for (int i = caller; i >= 0; i--)
        {
            if (caller > 5 && i == caller - 2) { parts.add("…"); i = 2; }
            parts.add(stack.frameNameAt(i));
        }
        return String.join(" → ", parts);
    }
}

package io.github.pluginprofiler;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ProfilerConfig.GROUP)
public interface ProfilerConfig extends Config
{
    String GROUP = "pluginprofiler";
    String HIDE_ZERO = "hideZeroUsage";
    String REFRESH_SECONDS = "panelRefreshSeconds";

    @ConfigItem(keyName = HIDE_ZERO, name = "Hide 0% Usage",
        description = "Hide rows that would display 0.0 or have no value for the selected ranking", hidden = true)
    default boolean hideZeroUsage() { return false; }

    @ConfigItem(keyName = REFRESH_SECONDS, name = "Panel refresh interval",
        description = "Seconds between updates to the visible ranking (1–60)", hidden = true)
    default int panelRefreshSeconds() { return 5; }
}

package io.github.pluginprofiler;

import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.JTextArea;
import javax.swing.ListSelectionModel;
import javax.swing.RowFilter;
import javax.swing.RowSorter;
import javax.swing.SortOrder;
import javax.swing.SwingConstants;
import javax.swing.table.AbstractTableModel;
import javax.swing.table.DefaultTableCellRenderer;
import javax.swing.table.TableColumn;
import javax.swing.table.TableRowSorter;
import net.runelite.client.ui.PluginPanel;

final class ProfilerPanel extends PluginPanel
{
    private enum Metric
    {
        LIVE("Last 60 sec"), SLOW_FRAMES("Slow-frame lift · 5 min"), SESSION("Session");

        private final String label;
        Metric(String label) { this.label = label; }
        @Override public String toString() { return label; }
    }

    private static final SampleHistory.Stats EMPTY = new SampleHistory.Stats();
    private final List<ProfilerPlugin.Entry> rows = new ArrayList<>();
    private final Model model = new Model();
    private final JTable table = new JTable(model);
    private final JComboBox<Metric> metric = new JComboBox<>(Metric.values());
    private final JCheckBox hideZero = new JCheckBox("Hide 0% Usage");
    private final TableRowSorter<Model> sorter = new TableRowSorter<Model>(model)
    {
        @Override public void toggleSortOrder(int column)
        {
            if (column != 1) { super.toggleSortOrder(column); return; }
            for (RowSorter.SortKey key : getSortKeys())
            {
                if (key.getColumn() == 3) { continue; }
                if (key.getColumn() == 1 && key.getSortOrder() == SortOrder.DESCENDING)
                {
                    sortMetric(SortOrder.ASCENDING);
                    return;
                }
                break;
            }
            sortMetric(SortOrder.DESCENDING);
        }
    };
    private final JTextArea suggestion = textArea();
    private final JTextArea message = textArea();
    private SampleHistory.Snapshot snapshot = new SampleHistory.Snapshot(Collections.emptyMap(), 0);

    ProfilerPanel(boolean hideInitially, Consumer<Boolean> saveHideZero)
    {
        super(false);
        setLayout(new BorderLayout(0, 5));
        setBorder(BorderFactory.createEmptyBorder(6, 5, 5, 5));
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        JPanel picker = new JPanel(new BorderLayout(4, 0));
        picker.add(new JLabel("Rank by"), BorderLayout.WEST);
        picker.add(metric, BorderLayout.CENTER);
        hideZero.setToolTipText("Hide zero and unavailable values for this metric");
        hideZero.addActionListener(e ->
        {
            setHideZero(hideZero.isSelected());
            saveHideZero.accept(hideZero.isSelected());
        });
        picker.setAlignmentX(LEFT_ALIGNMENT);
        header.add(picker);
        hideZero.setAlignmentX(LEFT_ALIGNMENT);
        header.add(hideZero);
        suggestion.setAlignmentX(LEFT_ALIGNMENT);
        suggestion.setVisible(false);
        header.add(suggestion);
        add(header, BorderLayout.NORTH);

        table.setRowHeight(23);
        table.setFillsViewportHeight(true);
        table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        table.getTableHeader().setReorderingAllowed(false);
        sorter.setSortsOnUpdates(true);
        table.setRowSorter(sorter);
        table.removeColumn(table.getColumnModel().getColumn(3));
        sortMetric(SortOrder.DESCENDING);
        fitHeader(1, "Share %");
        fitHeader(2, "Status");
        table.setDefaultRenderer(Double.class, new DefaultTableCellRenderer()
        {
            @Override protected void setValue(Object value)
            {
                setHorizontalAlignment(SwingConstants.RIGHT);
                setText(value == null ? "—" : String.format(Locale.ROOT, "%.1f", (Double) value));
            }
        });
        table.getColumnModel().getColumn(2).setCellRenderer(new DefaultTableCellRenderer()
        {
            @Override protected void setValue(Object value)
            {
                setHorizontalAlignment(SwingConstants.CENTER);
                setText(Boolean.TRUE.equals(value) ? "On" : "Off");
            }
        });
        JScrollPane list = new JScrollPane(table);
        add(list, BorderLayout.CENTER);

        message.setVisible(false);
        add(message, BorderLayout.SOUTH);
        metric.addActionListener(e ->
        {
            table.getColumnModel().getColumn(1).setHeaderValue(metric.getSelectedItem() == Metric.SLOW_FRAMES ? "Δ pp" : "Share %");
            table.getTableHeader().repaint();
            sortMetric(SortOrder.DESCENDING);
            describeMetric();
            refreshMetrics();
        });

        setHideZero(hideInitially);
        describeMetric();
    }

    private void describeMetric()
    {
        String meaning = metric.getSelectedItem() == Metric.SLOW_FRAMES
            ? "Over five minutes, share during slow frames (50 ms or longer) minus share during normal frames, in percentage points."
            : "Percentage of all main-thread samples attributed to this plugin. Includes time spent waiting.";
        metric.setToolTipText(meaning);
        table.getTableHeader().setToolTipText(meaning);
    }

    private void fitHeader(int col, String text)
    {
        TableColumn column = table.getColumnModel().getColumn(col);
        Component renderer = table.getTableHeader().getDefaultRenderer()
            .getTableCellRendererComponent(table, text, false, false, -1, col);
        int width = Math.max(renderer.getPreferredSize().width,
            table.getTableHeader().getFontMetrics(table.getTableHeader().getFont()).stringWidth(text) + 26);
        column.setMinWidth(width);
        column.setPreferredWidth(width);
        column.setMaxWidth(width);
    }

    void setHideZero(boolean hide)
    {
        hideZero.setSelected(hide);
        sorter.setRowFilter(hide ? new RowFilter<Model, Integer>()
        {
            @Override public boolean include(Entry<? extends Model, ? extends Integer> row)
            {
                Double value = (Double) row.getValue(1);
                return value != null && Math.abs(value) >= 0.05;
            }
        } : null);
    }

    private void sortMetric(SortOrder order)
    {
        List<RowSorter.SortKey> keys = new ArrayList<>();
        if (metric.getSelectedItem() != Metric.SESSION) { keys.add(new RowSorter.SortKey(3, SortOrder.DESCENDING)); }
        keys.add(new RowSorter.SortKey(1, order));
        keys.add(new RowSorter.SortKey(0, SortOrder.ASCENDING));
        sorter.setSortKeys(keys);
    }

    private static JTextArea textArea()
    {
        JTextArea area = new JTextArea();
        area.setEditable(false);
        area.setOpaque(false);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        return area;
    }

    private int selectedId()
    {
        int selected = table.getSelectedRow();
        return selected < 0 ? -1 : rows.get(table.convertRowIndexToModel(selected)).id;
    }

    void setRoster(List<ProfilerPlugin.Entry> entries)
    {
        int selected = selectedId();
        table.clearSelection();
        rows.clear();
        rows.addAll(entries);
        refresh(selected);
    }

    void update(SampleHistory.Snapshot latest)
    {
        snapshot = latest;
        ProfilerPlugin.Entry candidate = null;
        double highest = 0;
        for (ProfilerPlugin.Entry entry : rows)
        {
            if (!entry.active) { continue; }
            Double lift = latest.slowDifference(latest.stats.getOrDefault(entry.id, EMPTY));
            if (lift != null && lift > highest)
            {
                candidate = entry;
                highest = lift;
            }
        }
        if (candidate == null) { suggestion.setText(""); }
        else
        {
            SampleHistory.Stats stats = latest.stats.get(candidate.id);
            String label = stats.onlyGuesses ? "Name guess in slow frames: " : "More frequent in slow frames: ";
            suggestion.setText(label + candidate.name);
        }
        suggestion.setVisible(candidate != null);
        refreshMetrics();
    }

    void notice(String text)
    {
        message.setText(text);
        message.setVisible(true);
    }

    private void refreshMetrics()
    {
        if (!rows.isEmpty()) { model.fireTableRowsUpdated(0, rows.size() - 1); }
    }

    private void refresh(int selected)
    {
        model.fireTableDataChanged();
        if (selected >= 0)
        {
            for (int i = 0; i < rows.size(); i++)
            {
                if (rows.get(i).id == selected)
                {
                    int view = table.convertRowIndexToView(i);
                    if (view >= 0) { table.setRowSelectionInterval(view, view); }
                    break;
                }
            }
        }
    }

    private final class Model extends AbstractTableModel
    {
        @Override public int getRowCount() { return rows.size(); }
        @Override public int getColumnCount() { return 4; }
        @Override public String getColumnName(int col) { return col == 0 ? "Plugin" : col == 1 ? "Share %" : col == 2 ? "Status" : "Running"; }
        @Override public Class<?> getColumnClass(int col) { return col == 0 ? String.class : col == 1 ? Double.class : Boolean.class; }
        @Override public Object getValueAt(int row, int col)
        {
            ProfilerPlugin.Entry e = rows.get(row);
            if (col == 0) { return e.name; }
            if (col == 2) { return e.enabled; }
            if (col == 3) { return e.active; }
            SampleHistory.Stats s = snapshot.stats.getOrDefault(e.id, EMPTY);
            switch ((Metric) metric.getSelectedItem())
            {
                case SESSION: return snapshot.total == 0 ? null : 100.0 * snapshot.session.getOrDefault(e.id, 0L) / snapshot.total;
                case SLOW_FRAMES: return snapshot.slowDifference(s);
                default: return snapshot.liveSamples == 0 ? null : 100.0 * s.liveSamples / snapshot.liveSamples;
            }
        }
    }
}

package io.github.pluginprofiler;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
