@PluginDescriptor(name = "Plugin Profiler",
    description = "Rank plugins by main-thread sample share and compare their activity during slow and normal frames",
    tags = {"performance", "diagnostics", "profiling"})
public class ProfilerPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(ProfilerPlugin.class);
    @Inject private Client client;
    @Inject private ClientToolbar toolbar;
    @Inject private DrawManager drawManager;
    @Inject private PluginManager plugins;
    @Inject private ConfigManager configs;
    @Inject private ProfilerConfig settings;
    @Inject private ScheduledExecutorService executor;

    static final class Entry
    {
        final int id;
        final String name;
        final boolean enabled;
        final boolean active;

        Entry(int id, String name, boolean enabled, boolean active)
        {
            this.id = id;
            this.name = name;
            this.enabled = enabled;
            this.active = active;
        }
    }

    static final class Session
    {
        final SampleHistory history = new SampleHistory();
        final Runnable draw = () -> history.frames.finish(System.nanoTime());
        final Map<Plugin, Integer> ids = new IdentityHashMap<>();
        final Map<Plugin, String> groups = new IdentityHashMap<>();
        final AtomicBoolean snapshotQueued = new AtomicBoolean();
        private final AtomicBoolean refreshOnShow = new AtomicBoolean();
        HierarchyListener visibilityListener;
        volatile boolean panelVisible;
        volatile OwnershipIndex index;
        volatile boolean refreshQueued;
        ScheduledFuture<?> future;
        private volatile long refreshInterval;
        private long lastUpdate;
        int nextId = 1;

        Session(int refreshSeconds) { setRefreshInterval(refreshSeconds); }

        void setRefreshInterval(int seconds)
        {
            refreshInterval = TimeUnit.SECONDS.toNanos(Math.max(1, Math.min(60, seconds)));
        }

        void setPanelVisible(boolean visible)
        {
            if (visible) { refreshOnShow.set(true); }
            panelVisible = visible;
        }

        boolean beginPanelUpdate(long now)
        {
            if (!panelVisible || (!refreshOnShow.get() && now - lastUpdate < refreshInterval)) { return false; }
            if (!snapshotQueued.compareAndSet(false, true)) { return false; }
            refreshOnShow.set(false);
            lastUpdate = now;
            return true;
        }
    }

    private volatile Session current;
    private ProfilerPanel panel;
    private NavigationButton nav;

    @Provides
    ProfilerConfig provideConfig(ConfigManager manager) { return manager.getConfig(ProfilerConfig.class); }

    @Override
    protected void startUp()
    {
        Session session = new Session(settings.panelRefreshSeconds());
        panel = new ProfilerPanel(settings.hideZeroUsage(),
            hidden -> configs.setConfiguration(ProfilerConfig.GROUP, ProfilerConfig.HIDE_ZERO, hidden));
        ProfilerPanel view = panel;
        session.visibilityListener = event ->
        {
            if ((event.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0) { session.setPanelVisible(view.isShowing()); }
        };
        view.addHierarchyListener(session.visibilityListener);
        nav = NavigationButton.builder().tooltip("Plugin Profiler").icon(icon()).priority(7).panel(panel).build();
        current = session;
        rebuild(session);
        toolbar.addNavigation(nav);
        drawManager.registerEveryFrameListener(session.draw);
        schedule(session);
    }

    @Override
    protected void shutDown()
    {
        Session session = current;
        current = null;
        if (session != null)
        {
            synchronized (session)
            {
                if (session.future != null) { session.future.cancel(false); }
            }
            drawManager.unregisterEveryFrameListener(session.draw);
            panel.removeHierarchyListener(session.visibilityListener);
        }
        if (nav != null) { toolbar.removeNavigation(nav); }
        nav = null;
        panel = null;
    }

    @Subscribe public void onPluginChanged(PluginChanged event) { queueRoster(); }
    @Subscribe public void onExternalPluginsChanged(ExternalPluginsChanged event) { queueRoster(); }
    @Subscribe public void onProfileChanged(ProfileChanged event) { queueRoster(); refreshSettings(); }

    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (ProfilerConfig.GROUP.equals(event.getGroup())
            && (ProfilerConfig.HIDE_ZERO.equals(event.getKey()) || ProfilerConfig.REFRESH_SECONDS.equals(event.getKey())))
        {
            refreshSettings();
        }
    }

    private void refreshSettings()
    {
        SwingUtilities.invokeLater(() ->
        {
            Session session = current;
            if (session == null) { return; }
            session.setRefreshInterval(settings.panelRefreshSeconds());
            panel.setHideZero(settings.hideZeroUsage());
        });
    }

    private void queueRoster()
    {
        Session session = current;
        if (session == null) { return; }
        synchronized (session)
        {
            if (session.refreshQueued) { return; }
            session.refreshQueued = true;
        }
        SwingUtilities.invokeLater(() ->
        {
            session.refreshQueued = false;
            if (current == session) { rebuild(session); }
        });
    }

    private void rebuild(Session session)
    {
        List<Plugin> loaded = new ArrayList<>(plugins.getPlugins());
        session.ids.keySet().retainAll(loaded);
        session.groups.keySet().retainAll(loaded);
        List<OwnershipIndex.Owner> owners = new ArrayList<>();
        List<Entry> entries = new ArrayList<>();
        for (Plugin plugin : loaded)
        {
            int id = session.ids.computeIfAbsent(plugin, ignored -> session.nextId++);
            String name = plugin.getName();
            boolean active = plugins.isPluginActive(plugin);
            if (!session.groups.containsKey(plugin))
            {
                session.groups.put(plugin, configGroup(plugin));
            }
            owners.add(new OwnershipIndex.Owner(id, name, session.groups.get(plugin), active));
            entries.add(new Entry(id, name, plugins.isPluginEnabled(plugin), active));
        }
        entries.sort(Comparator.comparing(e -> e.name, String.CASE_INSENSITIVE_ORDER));
        session.index = new OwnershipIndex(owners);
        panel.setRoster(entries);
    }

    private String configGroup(Plugin plugin)
    {
        try
        {
            Config config = plugins.getPluginConfigProxy(plugin);
            if (config != null) { return configs.getConfigDescriptor(config).getGroup().value(); }
        }
        catch (RuntimeException ex)
        {
            LOG.debug("Could not read config alias for {}", plugin.getName(), ex);
        }
        return null;
    }

    private void schedule(Session session)
    {
        synchronized (session)
        {
            if (current == session)
            {
                long delay = ThreadLocalRandom.current().nextLong(80, 141);
                session.future = executor.schedule(() -> sample(session), delay, TimeUnit.MILLISECONDS);
            }
        }
    }

    private void sample(Session session)
    {
        if (current != session) { return; }
        try
        {
            OwnershipIndex index = session.index;
            long start = System.nanoTime();
            ClientThreadStack stack = ClientThreadStack.capture(client);
            long now = System.nanoTime();
            if (stack.size() != 0 && index == session.index)
            {
                session.history.record(start + (now - start) / 2, index, stack);
            }
            else
            {
                // A missing stack must not prevent old method paths from expiring.
                session.history.advance(now);
            }
            if (session.beginPanelUpdate(now))
            {
                SampleHistory.Snapshot snapshot = session.history.snapshot(now);
                SwingUtilities.invokeLater(() ->
                {
                    try
                    {
                        if (current == session && session.panelVisible) { panel.update(snapshot); }
                    }
                    finally { session.snapshotQueued.set(false); }
                });
            }
        }
        catch (RuntimeException ex)
        {
            session.history.clearWindow();
            LOG.warn("Main-thread sampling stopped", ex);
            SwingUtilities.invokeLater(() ->
            {
                if (current == session) { panel.notice("Sampling stopped. See the client log for details."); }
            });
            return;
        }
        schedule(session);
    }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(105, 205, 202));
        g.fillRect(1, 10, 3, 5);
        g.fillRect(6, 6, 3, 9);
        g.fillRect(11, 1, 3, 14);
        g.dispose();
        return image;
    }
}

package io.github.pluginprofiler;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

final class SampleHistory
{
    static final long LIVE_WINDOW = TimeUnit.SECONDS.toNanos(60);
    static final long FRAME_WINDOW = TimeUnit.MINUTES.toNanos(5);
    static final long SLOW = TimeUnit.MILLISECONDS.toNanos(50);
    static final long MAX_FRAME = TimeUnit.SECONDS.toNanos(2);

    // Only the tiny timestamp ring is shared with the render thread.
    static final class Frames
    {
        private final long[] times = new long[512];
        private int next;
        private int size;

        synchronized void finish(long time)
        {
            times[next] = time;
            next = (next + 1) % times.length;
            size = Math.min(size + 1, times.length);
        }

        synchronized boolean classify(Shot shot)
        {
            if (size < 2) { return false; }
            int cur = (next + times.length - 1) % times.length;
            if (times[cur] < shot.time) { return false; }
            for (int n = 1; n < size; n++)
            {
                int prev = (cur + times.length - 1) % times.length;
                if (times[prev] < shot.time)
                {
                    long interval = times[cur] - times[prev];
                    if (interval <= MAX_FRAME)
                    {
                        shot.frame = times[cur];
                        shot.frameType = interval >= SLOW ? FrameType.SLOW : FrameType.NORMAL;
                    }
                    break;
                }
                cur = prev;
            }
            return true;
        }
    }

    enum FrameType { UNMEASURED, NORMAL, SLOW }

    static final class Shot
    {
        final long time;
        final OwnershipIndex.Observation observation;
        long frame;
        FrameType frameType = FrameType.UNMEASURED;

        Shot(long time, OwnershipIndex.Observation observation)
        {
            this.time = time;
            this.observation = observation;
        }
    }

    static final class Stats
    {
        int liveSamples;
        int slow;
        int normal;
        int slowFrames;
        long previousSlow = Long.MIN_VALUE;
        boolean onlyGuesses = true;

        void count(Shot shot, OwnershipIndex.Match match, boolean inLiveWindow)
        {
            if (inLiveWindow) { liveSamples++; }
            if (match.evidence != OwnershipIndex.Evidence.GUESS) { onlyGuesses = false; }
            if (shot.frameType == FrameType.NORMAL) { normal++; }
            if (shot.frameType == FrameType.SLOW)
            {
                slow++;
                if (previousSlow != shot.frame)
                {
                    slowFrames++;
                    previousSlow = shot.frame;
                }
            }
        }
    }

    static final class Snapshot
    {
        final Map<Integer, Stats> stats = new HashMap<>();
        final Map<Integer, Long> session;
        final long total;
        int liveSamples;
        int slow;
        int normal;

        Snapshot(Map<Integer, Long> session, long total)
        {
            this.session = session;
            this.total = total;
        }

        Double slowDifference(Stats row)
        {
            if (slow < 10 || normal < 10 || row.slowFrames < 3) { return null; }
            return 100.0 * row.slow / slow - 100.0 * row.normal / normal;
        }
    }

    final Frames frames = new Frames();
    private final Deque<Shot> recent = new ArrayDeque<>();
    private final Deque<Shot> awaitingFrame = new ArrayDeque<>();
    private final OwnershipIndex.Learned learned = new OwnershipIndex.Learned();
    private final Map<OwnershipIndex.Signature, Long> session = new HashMap<>();
    private long total;

    // Owned by the sampler worker. Snapshots are handed to Swing after construction.
    void record(long time, OwnershipIndex roster, ClientThreadStack stack)
    {
        OwnershipIndex.Observation observation = roster.observe(stack, learned);
        Shot shot = new Shot(time, observation);
        recent.add(shot);
        awaitingFrame.add(shot);
        session.merge(observation.signature, 1L, Long::sum);
        total++;
        advance(time);
    }

    void advance(long now)
    {
        while (!awaitingFrame.isEmpty())
        {
            Shot shot = awaitingFrame.peek();
            if (!frames.classify(shot) && now - shot.time <= MAX_FRAME) { break; }
            awaitingFrame.remove();
        }
        while (!recent.isEmpty() && now - recent.peek().time > FRAME_WINDOW) { recent.remove(); }
    }

    void clearWindow()
    {
        recent.clear();
        awaitingFrame.clear();
    }

    Snapshot snapshot(long now)
    {
        advance(now);
        Map<Integer, Long> totals = new HashMap<>();
        session.forEach((signature, count) -> totals.merge(signature.resolve(learned).id, count, Long::sum));
        Snapshot result = new Snapshot(totals, total);
        for (Shot shot : recent)
        {
            boolean inLiveWindow = now - shot.time <= LIVE_WINDOW;
            if (inLiveWindow) { result.liveSamples++; }
            OwnershipIndex.Match owner = shot.observation.signature.resolve(learned);
            if (owner.id != 0) { result.stats.computeIfAbsent(owner.id, ignored -> new Stats()).count(shot, owner, inLiveWindow); }
            if (shot.frameType == FrameType.SLOW) { result.slow++; }
            if (shot.frameType == FrameType.NORMAL) { result.normal++; }
        }
        return result;
    }

    // Build a method-level histogram on demand. Swing snapshots carry numeric aggregates only.
    Map<String, Integer> recentPathCounts(long now, int pluginId)
    {
        advance(now);
        Map<String, Integer> counts = new HashMap<>();
        if (pluginId == 0) { return counts; }
        for (Shot shot : recent)
        {
            OwnershipIndex.Observation observation = shot.observation;
            if (observation.signature.resolve(learned).id == pluginId)
            {
                counts.merge(observation.path, 1, Integer::sum);
            }
        }
        return counts;
    }
}

